<div class="col-xl-12"><div class="card"><div class="card-header"><h4>Stock Card (latest 200)</h4></div><div class="card-body"><div class="table-responsive"><table class="table" id="myTable"><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Before</th><th>Change</th><th>After</th><th>Cost</th><th>User</th><th>Notes</th></tr></thead><tbody>@foreach ($movements as $movement)<tr><td>{{ $movement->created_at->format('d M Y H:i') }}</td><td>{{ $movement->product->name }}</td><td>{{ strtoupper(str_replace('_',' ',$movement->movement_type)) }}</td><td>{{ $movement->quantity_before }}</td><td class="{{ $movement->quantity_change >= 0 ? 'text-success' : 'text-danger' }}">{{ $movement->quantity_change >= 0 ? '+' : '' }}{{ $movement->quantity_change }}</td><td>{{ $movement->quantity_after }}</td><td>Rp. {{ number_format($movement->unit_cost,0,',','.') }}</td><td>{{ optional($movement->creator)->full_name }}</td><td>{{ $movement->notes }}</td></tr>@endforeach</tbody></table></div></div></div></div>
<div class="modal fade" id="adjustStock"><div class="modal-dialog modal-lg modal-dialog-centered"><form class="modal-content" action="{{ route('pos-stock.adjust') }}" method="POST" id="adjustForm">@csrf<input type="hidden" name="idempotency_key" value="{{ $idempotencyKey }}"><div class="modal-header"><h5>Stock Adjustment</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-warning">Isi angka positif untuk menambah, angka negatif untuk mengurangi. Stok tidak boleh menjadi minus.</div><div class="mb-3"><label class="form-label">Reason</label><textarea class="form-control" name="reason" required></textarea></div><table class="table" id="adjustItems"><thead><tr><th>Product</th><th>Change (+/-)</th><th></th></tr></thead><tbody></tbody></table><button class="btn btn-outline-primary" type="button" id="addAdjustLine">+ Add Product</button></div><div class="modal-footer"><button class="btn btn-primary" type="submit">Save Adjustment</button></div></form></div></div>
<template id="adjustRow"><tr><td><select class="form-control product" required><option value="">-- Choose --</option>@foreach ($products as $item)<option value="{{ $item->product_id }}">{{ $item->product->name }} (stock {{ $item->stock_qty }})</option>@endforeach</select></td><td><input type="number" step="0.001" class="form-control change" required></td><td><button type="button" class="btn btn-danger btn-xs remove">×</button></td></tr></template>
<script>document.addEventListener('DOMContentLoaded',function(){const body=document.querySelector('#adjustItems tbody'),tpl=document.querySelector('#adjustRow');function reindex(){body.querySelectorAll('tr').forEach((r,i)=>{r.querySelector('.product').name=`items[${i}][product_id]`;r.querySelector('.change').name=`items[${i}][quantity_change]`;});}function add(){body.appendChild(tpl.content.cloneNode(true));reindex();}document.querySelector('#addAdjustLine').onclick=add;body.onclick=e=>{if(e.target.classList.contains('remove')){e.target.closest('tr').remove();reindex();}};document.querySelector('#adjustForm').onsubmit=function(){this.querySelector('[type=submit]').disabled=true;};add();});</script>
